const int maxn = 1e5 + 5;
pair<int, int> a[maxn];
long long dist[maxn][31];
int n;
map<int, vector<int>> row;
map<int, vector<int>> col;
map<int, vector<int>> diag;
bool check(int ux, int uy, int i_x, int i_y, int d) {
    int dx = i_x - ux;
    int dy = i_y - uy;
    if (dx < 0 || dy < 0) return false;
    if (dy == 0 && dx % d == 0) return true;
    if (dx == 0 && dy % d == 0) return true;
    if (dx > 0 && dx == dy && dx % d == 0) return true;
    
    return false;
}
vector<int> query(int u_idx, int d) {
    vector<int> ans;
    int x = a[u_idx].first;
    int y = a[u_idx].second;
    auto it_r = row.find(y);
    if (it_r != row.end()) {
        const auto& vec = it_r->second;
        auto start = upper_bound(vec.begin(), vec.end(), x, [](int val, int idx) {
            return val < a[idx].first;
        });
        for (auto it = start; it != vec.end(); ++it) {
            if ((a[*it].first - x) % d == 0) {
                ans.push_back(*it);
                break;
            }
        }
    }
    auto it_c = col.find(x);
    if (it_c != col.end()) {
        const auto& vec = it_c->second;
        auto start = upper_bound(vec.begin(), vec.end(), y, [](int val, int idx) {
            return val < a[idx].second;
        });
        for (auto it = start; it != vec.end(); ++it) {
            if ((a[*it].second - y) % d == 0) {
                ans.push_back(*it);
                break;
            }
        }
    }

    auto it_d = diag.find(y - x);
    if (it_d != diag.end()) {
        const auto& vec = it_d->second;
        auto start = upper_bound(vec.begin(), vec.end(), x, [](int val, int idx) {
            return val < a[idx].first;
        });
        for (auto it = start; it != vec.end(); ++it) {
            if ((a[*it].first - x) % d == 0) {
                ans.push_back(*it);
                break;
            }
        }
    }

    return ans;
}
long long calc(int u, int v, int x, int y, int d) {
    long long dx = abs(u - x);
    long long dy = abs(v - y);
    return max(dx, dy) / d;
}
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cin >> n;
    int x, y;
    cin >> x >> y;
    for(int i = 1; i <= n; i++) {
        cin >> a[i].first >> a[i].second;
    }
    a[n + 1] = {x, y};
    n++;
    for (int i = 0; i <= n; i++) {
        row[a[i].second].push_back(i);
        col[a[i].first].push_back(i);
        diag[a[i].second - a[i].first].push_back(i);
    }
    for (auto& [key, vec] : row) {
        sort(vec.begin(), vec.end(), [](int i, int j) {
            return a[i].first < a[j].first;
        });
    }
    for (auto& [key, vec] : col) {
        sort(vec.begin(), vec.end(), [](int i, int j) {
            return a[i].second < a[j].second;
        });
    }
    for (auto& [key, vec] : diag) {
        sort(vec.begin(), vec.end(), [](int i, int j) {
            return a[i].first < a[j].first;
        });
    }
    priority_queue<tuple<long long, long long, long long>, vector<tuple<long long, long long, long long>>, greater<tuple<long long, long long, long long>>> pq;
    pq.push({0, 1, 0});
    for(int i = 0; i <= n; i++) {
        for(int j = 0; j < 31; j++) {
            dist[i][j] = 1e18;
        }
    }
    dist[0][0] = 0;
    while(!pq.empty()) {
        auto [d, x, u] = pq.top();
        pq.pop();
        int cl = __builtin_ctz(x); 
        
        if (d > dist[u][cl]) continue;

        vector<pair<long long, long long>> transitions;
        if (u <= n) {
            transitions.push_back({x, cl});
            if (cl + 1 < 31) transitions.push_back({x * 2, cl + 1});
            if (cl > 0)     transitions.push_back({x / 2, cl - 1});
            transitions.push_back({1, 0});
        } else {
            transitions.push_back({x, cl});
        }
        for (auto [nx, nl] : transitions) {
            for (int i : query(u, nx)) {
                long long cost = calc(a[u].first, a[u].second, a[i].first, a[i].second, nx);
                if (dist[u][cl] + cost < dist[i][nl]) {
                    dist[i][nl] = dist[u][cl] + cost;
                    pq.push({dist[i][nl], nx, i});
                }
            }
        }
    }
    long long ans = *min_element(dist[n], dist[n] + 31);
    if(ans >= 1e18) {
        cout << -1;
    } else {
        cout << ans;
    }
}